// HasCanonicalParty applies the HasEdge predicate on the "canonical_party" edge.
func HasCanonicalParty() predicate.Party {
	return predicate.Party(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CanonicalPartyTable, CanonicalPartyColumn),
		)
		schemaConfig := internal.SchemaConfigFromContext(s.Context())
		step.To.Schema = schemaConfig.Party
		step.Edge.Schema = schemaConfig.Party
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCanonicalPartyWith applies the HasEdge predicate on the "canonical_party" edge with a given conditions (other predicates).
func HasCanonicalPartyWith(preds ...predicate.Party) predicate.Party {
	return predicate.Party(func(s *sql.Selector) {
		step := newCanonicalPartyStep()
		schemaConfig := internal.SchemaConfigFromContext(s.Context())
		step.To.Schema = schemaConfig.Party
		step.Edge.Schema = schemaConfig.Party
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

